import { inject, Injectable } from '@angular/core';
import { ApiServiceService } from '../../../services/api/api-service.service';
import { BehaviorSubject, firstValueFrom, last, lastValueFrom, } from 'rxjs';
import { UtilsEstadoCuentaService } from '../../estado-cuenta/services/utils-estado-cuenta.service';
import { Credito } from '../../../models/credito.model';

export type ConsolidadoRow = Record<string, string | number>

export interface FilterOptions {
    fecha_inicio?: string;
    fecha_fin?: string;
    producto_financiero_id?: number;
}

@Injectable()
export abstract class GenericSuperConsolidadoService<T = Credito> {
    protected abstract endpoint: string

    abstract filter: (credito: T, options?: FilterOptions) => boolean

    abstract map: (credito: T, options?: FilterOptions) => ConsolidadoRow

    protected perPage = 4000

    protected dataSource: T[] = []

    protected yieldInterval = 250

    //progress
    protected progressSubject = new BehaviorSubject<number>(0);
    public progress$ = this.progressSubject.asObservable();

    //services
    private api = inject(ApiServiceService)
    protected utilsEstadoCuenta = inject(UtilsEstadoCuentaService)

    public async fetchDataMaped(options?: FilterOptions): Promise<ConsolidadoRow[]> {
        await this.ensureFetchDataIsFinish()

        return this.mapLargeArray(await this.filteredLargeArray(options), options)
    }

    public async fetchData(options?: FilterOptions): Promise<T[]> {
        await this.ensureFetchDataIsFinish()

        const data = await this.filteredLargeArray(options)

        return data
    }

    protected async initData(): Promise<void> {
        try {
            // 1. Obtener metadatos iniciales
            const firstPage = await firstValueFrom(
                this.api.get<T[]>(`${this.endpoint}/total`, { page: 1, per_page: this.perPage }, false)
            );
            const totalPages = firstPage.total_pages ?? 0;

            if (totalPages === 0) {
                this.progressSubject.next(100);
                this.progressSubject.complete();
                return;
            }

            // 2. Inicializar estructuras de datos
            const allData: T[] = [];
            const uniqueIds = new Set<number>();
            const pages = Array.from({ length: totalPages }, (_, i) => i + 1);
            const chunkSize = 5;

            // 3. Procesar por chunks
            for (let i = 0; i < pages.length; i += chunkSize) {
                const chunk = pages.slice(i, i + chunkSize);

                // Procesar cada página del chunk secuencialmente
                for (const page of chunk) {
                    const data = await this.processPage(page, uniqueIds);
                    allData.push(...data);
                    this.progressSubject.next((page / pages.length) * 100);
                }
            }

            // 4. Asignar todos los datos al final
            this.dataSource = allData;
            this.progressSubject.next(100);
            this.progressSubject.complete();

        } catch (error) {
            this.progressSubject.error(error);
            throw error;
        }
    }

    private async processPage(page: number, uniqueIds: Set<number>): Promise<T[]> {
        const response = await firstValueFrom(
            this.api.get<T[]>(this.endpoint, { page, per_page: this.perPage }, false)
        );

        if (!response.status) {
            throw new Error('Error en el server');
        }

        const newData = (response.data ?? [])

        return newData;
    }

    protected async ensureFetchDataIsFinish(): Promise<void> {
        // Si ya está completo y llegó al 100%, retornar inmediatamente
        if (this.progressSubject.closed && this.progressSubject.value === 100) {
            return;
        }

        if (this.dataSource.length) {
            return
        }

        try {
            await lastValueFrom(
                this.progress$.pipe(
                    last(),
                )
            );
        } catch (error) {
            throw new Error('Error esperando finalización: ' + error);
        }
    }

    /**
     * Convierte un valor a número y aplica redondeo inteligente:
     * - Redondea hacia abajo si la diferencia es inferior a 0.10
     * - Redondea hacia arriba si la diferencia es 0.90 o superior
     * - Redondea normalmente para valores intermedios
     * @param value Valor a convertir (string o number)
     * @returns Número convertido y redondeado
     */
    public parseToNumber(value: string | number): number {
        // Convertir a número
        const num = typeof value === 'string'
            ? parseFloat(value)
            : value;

        if (isNaN(num)) {
            throw new Error('El valor proporcionado no es un número válido');
        }

        return +num.toFixed(2);
    }

    /**
     * Mapea grandes arrays sin bloquear el navegador
     * @param data Array de entrada
     * @param mapper Función de transformación
     * @param chunkSize Tamaño de los chunks (default: 100)
     * @param yieldInterval Milisegundos para liberar el event loop (default: 0)
     */
    protected async mapLargeArray(
        data: T[],
        options: FilterOptions | undefined,
        chunkSize = 100,
        yieldInterval = this.yieldInterval
    ): Promise<ConsolidadoRow[]> {
        const results: ConsolidadoRow[] = [];

        for (let i = 0; i < data.length; i += chunkSize) {
            const chunk = data.slice(i, i + chunkSize);

            // Procesar chunk actual (puedes usar Promise.all si el mapper es async)
            const chunkResults = chunk.map(c => this.map(c, options));
            results.push(...chunkResults);

            // Liberar el event loop periódicamente
            if (yieldInterval > 0 && i % (chunkSize * 10) === 0) {
                await new Promise(resolve => setTimeout(resolve, yieldInterval));
            }
        }

        return results;
    }

    // Si la clase es genérica (ej: class MiClase<T> { ... })
    protected async filteredLargeArray(
        options: FilterOptions | undefined,
        chunkSize = 500,
        yieldInterval = this.yieldInterval
    ): Promise<T[]> {
        const result: T[] = [];

        for (let i = 0; i < this.dataSource.length; i += chunkSize) {
            const chunk: T[] = this.dataSource.slice(i, i + chunkSize);

            // Filtrar el chunk actual
            const filteredChunk: T[] = chunk.filter(c => this.filter(c, options));
            result.push(...filteredChunk);

            // Liberar el event loop periódicamente
            if (yieldInterval > 0 && i % (chunkSize * 10) === 0) {
                await new Promise(resolve => setTimeout(resolve, yieldInterval));
            }
        }

        return result;
    }

    /**
     * Ejecuta forEach en grandes arrays sin bloquear el navegador
     * @param data Array de entrada
     * @param callback Función a ejecutar por cada elemento
     * @param chunkSize Tamaño de los chunks (default: 500)
     * @param yieldInterval Milisegundos para liberar el event loop (default: 0)
     */
    protected async forEachLargeArray(
        data: T[],
        callback: (item: T, index: number, array: T[]) => void,
        chunkSize = 500,
        yieldInterval = this.yieldInterval
    ): Promise<void> {
        for (let i = 0; i < data.length; i += chunkSize) {
            const chunk = data.slice(i, i + chunkSize);

            // Procesar chunk actual
            chunk.forEach(callback);

            // Liberar el event loop periódicamente
            if (yieldInterval > 0 && i % (chunkSize * 10) === 0) {
                await new Promise(resolve => setTimeout(resolve, yieldInterval));
            }
        }
    }

}
