import { ConsolidadoHistoricoInforme } from '../../../../../reportes/models/consolidado.historico.informe';
import { ReporteEjercicioFiscal, Programa, DatosMunicipio, TotalCategoria, MetricasPrograma } from '../../../interfaces/por-programa-data';

/**
 * Función reutilizable para transformar datos del consolidado histórico a ReporteEjercicioFiscal
 */
export function mapearConsolidadoHistoricoAReporte(datos: ConsolidadoHistoricoInforme[]): ReporteEjercicioFiscal[] {
    if (!datos.length) return [];

    // Agrupar por año
    const datosPorAño = new Map<number, ConsolidadoHistoricoInforme[]>();

    datos.forEach(dato => {
        if (dato.periodo && dato.periodo !== 'NO APLICA') {
            const año = new Date(dato.periodo).getFullYear();
            if (!datosPorAño.has(año)) {
                datosPorAño.set(año, []);
            }
            datosPorAño.get(año)!.push(dato);
        }
    });

    // Transformar cada año a ReporteEjercicioFiscal
    return Array.from(datosPorAño.entries()).map(([año, datosAnio]) => {
        return crearReportePorAño(año, datosAnio);
    }).sort((a, b) => a.año - b.año);
}

/**
 * Crea un ReporteEjercicioFiscal para un año específico
 */
function crearReportePorAño(año: number, datos: ConsolidadoHistoricoInforme[]): ReporteEjercicioFiscal {
    // Agrupar por municipio
    const datosPorMunicipio = new Map<string, ConsolidadoHistoricoInforme[]>();

    datos.forEach(dato => {
        const municipio = dato.ciudad || 'No especificado';
        if (!datosPorMunicipio.has(municipio)) {
            datosPorMunicipio.set(municipio, []);
        }
        datosPorMunicipio.get(municipio)!.push(dato);
    });

    // Crear municipios con sus programas y totales
    const municipiosArray = Array.from(datosPorMunicipio.entries()).map(([municipio, datosMunicipio]) => {
        return crearDatosMunicipio(municipio, datosMunicipio);
    });

    // Calcular totales generales
    const totalGeneral = calcularTotalGeneral(municipiosArray);

    return {
        año,
        municipios: municipiosArray,
        totalGeneral
    };
}

/**
 * Crea datos de municipio con programas y totales
 */
function crearDatosMunicipio(municipio: string, datos: ConsolidadoHistoricoInforme[]): DatosMunicipio {
    // Agrupar por programa
    const programasPorNombre = new Map<string, ConsolidadoHistoricoInforme[]>();

    datos.forEach(dato => {
        const programa = dato.programa || 'No especificado';
        if (!programasPorNombre.has(programa)) {
            programasPorNombre.set(programa, []);
        }
        programasPorNombre.get(programa)!.push(dato);
    });

    // Crear programas
    const programasArray = Array.from(programasPorNombre.entries()).map(([nombre, datosPrograma]) => {
        return crearPrograma(nombre, datosPrograma);
    });

    // Calcular totales por categoría
    const apoyos = calcularTotalCategoria(datos.filter(d => d.tipo_programa_apoyos_creditos === 'APOYOS'));
    const credito = calcularTotalCategoria(datos.filter(d => d.tipo_programa_apoyos_creditos === 'CREDITOS'));
    const ejercicio = calcularTotalCategoria(datos);

    return {
        municipio,
        programas: programasArray,
        apoyos,
        credito,
        ejercicio
    };
}

/**
 * Crea un programa con sus métricas
 */
function crearPrograma(nombre: string, datos: ConsolidadoHistoricoInforme[]): Programa {
    const primerDato = datos[0];
    const tipo = primerDato?.tipo_programa_apoyos_creditos === 'CREDITOS' ? 'credito' : 'apoyo';

    // Calcular métricas del programa
    const metricas: MetricasPrograma = {
        solicitudes: datos.length,
        monto: datos.reduce((sum, d) => sum + +(d.monto_autorizado || 0), 0),
        mujeres: datos.filter(d => d.genero === 'MUJER').length,
        hombres: datos.filter(d => d.genero === 'HOMBRE').length
    };

    return {
        nombre,
        tipo,
        metricas
    };
}

/**
 * Calcula totales para una categoría específica
 */
function calcularTotalCategoria(datos: ConsolidadoHistoricoInforme[]): TotalCategoria {
    return {
        solicitudes: datos.length,
        monto: datos.reduce((sum, d) => sum + +(d.monto_autorizado || 0), 0),
        mujeres: datos.filter(d => d.genero === 'MUJER').length,
        hombres: datos.filter(d => d.genero === 'HOMBRE').length
    };
}

/**
 * Calcula totales generales de todos los municipios
 */
function calcularTotalGeneral(municipios: DatosMunicipio[]): TotalCategoria {
    return municipios.reduce((total, municipio) => ({
        solicitudes: total.solicitudes + municipio.ejercicio.solicitudes,
        monto: total.monto + municipio.ejercicio.monto,
        mujeres: total.mujeres + municipio.ejercicio.mujeres,
        hombres: total.hombres + municipio.ejercicio.hombres
    }), { solicitudes: 0, monto: 0, mujeres: 0, hombres: 0 });
}

/**
 * Agrupa datos por campo específico
 */
export function agruparPorCampo<T>(datos: T[], campoGetter: (item: T) => string): Map<string, T[]> {
    const resultado = new Map<string, T[]>();

    datos.forEach(item => {
        const clave = campoGetter(item);
        if (!resultado.has(clave)) {
            resultado.set(clave, []);
        }
        resultado.get(clave)!.push(item);
    });

    return resultado;
}

/**
 * Filtra datos por rango de fechas
 */
export function filtrarPorFechas(
    datos: ConsolidadoHistoricoInforme[],
    fechaInicio: Date,
    fechaFin: Date
): ConsolidadoHistoricoInforme[] {
    return datos.filter(dato => {
        if (!dato.periodo || dato.periodo === 'NO APLICA') {
            return false;
        }

        const fechaRegistro = new Date(dato.periodo);
        fechaRegistro.setHours(12, 0, 0, 0); // Mediodía para evitar problemas de timezone

        return fechaRegistro >= fechaInicio && fechaRegistro <= fechaFin;
    });
}

/**
 * Calcula estadísticas básicas de un array numérico
 */
export function calcularEstadisticas(numeros: number[]): {
    total: number;
    promedio: number;
    minimo: number;
    maximo: number;
    cantidad: number;
} {
    const cantidad = numeros.length;
    if (cantidad === 0) {
        return { total: 0, promedio: 0, minimo: 0, maximo: 0, cantidad: 0 };
    }

    const total = numeros.reduce((sum, num) => sum + num, 0);
    const promedio = total / cantidad;
    const minimo = Math.min(...numeros);
    const maximo = Math.max(...numeros);

    return { total, promedio, minimo, maximo, cantidad };
}