import { Component, signal, computed, inject } from '@angular/core';
import { ReporteEjercicioFiscal } from '../../interfaces/por-programa-data';
import { ConsolidadoHistoricoCombinadoService } from '../../../../reportes/services/consolidado-historico-combinado.service';
import { ConsolidadoHistoricoInforme } from '../../../../reportes/models/consolidado.historico.informe';
import { MainInformeComponent } from "../../shared/main-informe/main-informe.component";
import { TablaPorProgramaEjercicioFiscalComponent } from "./components/tabla-por-programa-ejercicio-fiscal/tabla-por-programa-ejercicio-fiscal.component";
import { FilterOptions } from '../../../services/consolidado.super.service';
import { mapearConsolidadoHistoricoAReporte } from './utils/data-mapping.utils';
import { POR_PROGRAMA_2021_DATA } from '../../data/por-programa-data';

@Component({
  selector: 'app-por-programas-section',
  imports: [MainInformeComponent, TablaPorProgramaEjercicioFiscalComponent],
  templateUrl: './por-programas-section.component.html',
  styleUrl: './por-programas-section.component.css'
})
export class PorProgramasSectionComponent {
  // Fechas de filtrado por defecto (últimos 4 años)
  fechaInicio = signal<string>('2022-01-01');
  fechaFin = signal<string>('2024-12-31');

  // Datos del servicio
  private consolidadoService = inject(ConsolidadoHistoricoCombinadoService);
  private rawData = signal<ConsolidadoHistoricoInforme[]>([]);

  // Reportes transformados usando función reutilizable
  reportes = computed<ReporteEjercicioFiscal[]>(() => {
    return [ POR_PROGRAMA_2021_DATA, ...mapearConsolidadoHistoricoAReporte(this.rawData())]
  });

  constructor() {
    this.cargarDatos();
  }

  async cargarDatos(): Promise<void> {
    const filterOptions: FilterOptions = {
      fecha_inicio: this.fechaInicio(),
      fecha_fin: this.fechaFin()
    };

    // Cargar datos del servicio
    const data = await this.consolidadoService.fetchData(filterOptions);
    this.rawData.set(data);
  }

  actualizarFechas(inicio: string, fin: string): void {
    this.fechaInicio.set(inicio);
    this.fechaFin.set(fin);
    this.cargarDatos();
  }
}
