import { Component, Input, inject, OnChanges, SimpleChanges, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { InformeTablaConfiguradaComponent } from '../../../informe-tabla-configurada/informe-tabla-configurada.component';
import { TablaConfig, TablaConfigurada } from '../../../informe-tabla-configurada/interfaces/tabla.configurada';
import { ConsolidadoHistoricoCombinadoService } from '../../../../reportes/services/consolidado-historico-combinado.service';
import { ConsolidadoRow } from '../../../services/consolidado.super.service';

@Component({
  selector: 'app-configuraciones-tablas-preview',
  imports: [InformeTablaConfiguradaComponent],
  templateUrl: './configuraciones-tablas-preview.component.html',
  styleUrl: './configuraciones-tablas-preview.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ConfiguracionesTablasPreviewComponent implements OnChanges {
  @Input() seccion: string = '';
  @Input() tablasConfiguradas: TablaConfigurada[] = [];

  private consolidadoService = inject(ConsolidadoHistoricoCombinadoService);
  private cdr = inject(ChangeDetectorRef)

  rawData: ConsolidadoRow[] = [];
  tablasPreparadas: TablaConfigurada[] = [];
  private _isInitialized = false;

  ngOnInit() {
    this.cargarDatos();
    this._isInitialized = true;
  }

  ngOnChanges(changes: SimpleChanges) {
    if (changes['tablasConfiguradas'] && this.tablasConfiguradas && this._isInitialized) {
      this.prepararTablas();
    }
  }

  /**
   * Prepara todas las configuraciones una sola vez cuando cambian los datos de entrada
   * Usando inmutabilidad para evitar cambios durante el rendering
   */
  private prepararTablas() {
    // Crear nuevo array para mantener inmutabilidad
    this.tablasPreparadas = this.tablasConfiguradas
      .filter(config => config.seccion === this.seccion)
      .map(config => this.crearTablaPreparada(config));
  }

  /**
   * Crea una copia inmutable de la tabla con la configuración preparada
   */
  private crearTablaPreparada(config: TablaConfigurada): TablaConfigurada {
    // Crear copia profunda inmutable
    const configPreparada: TablaConfigurada = {
      ...config,
      configuracion: this.prepararConfiguracionPreview(config.configuracion)
    };
    return configPreparada;
  }

  async cargarDatos() {
    try {
      this.rawData = await this.consolidadoService.fetchDataMaped();
      // Preparar tablas después de cargar los datos
      if (this.tablasConfiguradas.length > 0) {
        this.prepararTablas();
        this.cdr.detectChanges()
      }
    } catch (error) {
      console.error('Error al cargar datos:', error);
      this.rawData = [];
    }
  }

  /**
   * Prepara la configuración para el modo preview
   * Establece showInTable = true solo para la vista predeterminada
   * Asegura que displayMode siempre se inicialice como 'table'
   */
  private prepararConfiguracionPreview(config: TablaConfig): TablaConfig  {
    if (!config.finalViews?.length) {
      return config;
    }

    // Clonar la configuración para no modificar el original
    const configPreview:TablaConfig = JSON.parse(JSON.stringify(config));
    if(!configPreview.filterBasedConfigs){
      configPreview.filterBasedConfigs=[]
    }

    // Si hay una vista predeterminada, establecer showInTable = true solo para esa vista
    if (configPreview.defaultViewId) {
      configPreview.finalViews = configPreview.finalViews.map((view: any) => ({
        ...view,
        showInTable: this.generarViewId(view.name) === configPreview.defaultViewId,
        displayMode: this.generarViewId(view.name) === configPreview.defaultViewId ? 'table' : (view.displayMode || 'table')
      }));
    } else {
      // Si no hay vista predeterminada, mostrar la primera
      configPreview.finalViews = configPreview.finalViews.map((view: any, index: number) => ({
        ...view,
        showInTable: index === 0,
        displayMode: index === 0 ? 'table' : (view.displayMode || 'table')
      }));
    }

    return configPreview;
  }

  /**
   * Obtiene el nombre descriptivo de la sección
   */
  getNombreSeccion(): string {
    const nombresSecciones: Record<string, string> = {
      'periodos': 'Por Periodos',
      'zona-prioritaria': 'Zona Prioritaria',
      'genero': 'Monto y Género',
      'empleos': 'Generación de Empleos',
      'sectores': 'Sectores Económicos',
      'discapacidades': 'Discapacidades',
      'etnias': 'Etnias',
      'montos': 'Montos y Género',
      'mes': 'Por Mes'
    };
    return nombresSecciones[this.seccion] || this.seccion;
  }

  /**
   * Genera un ID único para una vista final basado en su nombre
   * (Método consistente con el usado en configuración-tablas-seccion)
   */
  private generarViewId(viewName: string): string {
    return viewName.toLowerCase()
      .replace(/[^a-z0-9]/g, '_')
      .replace(/_+/g, '_')
      .replace(/^_|_$/g, '') || 'vista_' + Date.now();
  }
}