import { Component, inject, OnInit, signal } from '@angular/core';
import { PorProgramasSectionComponent } from "./components/por-programas-section/por-programas-section.component";
import { ConfiguracionesTablasPreviewComponent } from "./components/configuraciones-tablas-preview/configuraciones-tablas-preview.component";
import { TablaConfiguradaService } from '../informe-tabla-configurada/services/tabla.configurada.service';
import { TablaConfigurada } from '../informe-tabla-configurada/interfaces/tabla.configurada';
import { ConsolidadoHistoricoCombinadoService } from '../../reportes/services/consolidado-historico-combinado.service';
import { ConsolidadoRow } from '../services/consolidado.super.service';
import { PorPeriodosAdministracionComponent } from "./components/por-periodos-section/components/por-periodos-administracion/por-periodos-administracion.component";
import { MainInformeComponent } from "./shared/main-informe/main-informe.component";
import { PorZonaPrioritariaComponent } from "./components/por-zona-prioritaria/por-zona-prioritaria.component";

export interface Tab {
  id:string;
  label:string;
  badge?:string;
  icon:string;
}

export const DASHBOARD_HISTORICO_SECCIONES=[
    { id: 'programas', label: 'Por Programas', icon: 'graph-up' },
    { id: 'periodos', label: 'Por Periodos', icon: 'calendar3' },
    { id: 'zona-prioritaria', label: 'Zona Prioritaria', icon: 'geo-alt' },
    { id: 'genero', label: 'Monto y Género', icon: 'gender-ambiguous' },
    { id: 'empleos', label: 'Generación de Empleos', icon: 'briefcase' },
    { id: 'sectores', label: 'Sectores Económicos', icon: 'buildings' },
    { id: 'discapacidades', label: 'Discapacidades', icon: 'universal-access' },
    { id: 'etnias', label: 'Etnias', icon: 'people' },
    { id: 'montos', label: 'Montos y Género', icon: 'cash-stack' },
    { id: 'mes', label: 'Por Mes', icon: 'calendar-month' },
  ]

@Component({
  selector: 'app-dashboard-historico',
  imports: [
    PorProgramasSectionComponent,
    ConfiguracionesTablasPreviewComponent,
    PorPeriodosAdministracionComponent,
    MainInformeComponent,
    PorZonaPrioritariaComponent
],
  templateUrl: './dashboard-historico.component.html',
  styleUrl: './dashboard-historico.component.css'
})
export class DashboardHistoricoComponent implements OnInit {
  activeTab = signal('programas');

  tabs: Tab[] = DASHBOARD_HISTORICO_SECCIONES;

  tablasConfiguradas:TablaConfigurada[]=[]
  rawData:ConsolidadoRow[]=[]

  //services
  private tablaConfiguradaController = inject(TablaConfiguradaService)
  private consolidadoService = inject(ConsolidadoHistoricoCombinadoService)

  ngOnInit(): void {
    this.setTablasConfiguradas()
    this.setConsolidadoData()
  }

  private async setTablasConfiguradas(){
    const data= await this.tablaConfiguradaController.all({
      conditionals:{
        deleted_at:null
      }
    })
    this.tablasConfiguradas= data.map(item => ({
      ...item,
      configuracion : JSON.parse(item.configuracion as string)
    }))
  }

  private async setConsolidadoData(){
    try {
      this.rawData = await this.consolidadoService.fetchDataMaped()
    } catch (error) {
      console.error('Error al cargar datos consolidados:', error)
      this.rawData = []
    }
  }

  /**
   * Filtra las tablas configuradas por sección
   */
  getTablasPorSeccion(seccion: string): TablaConfigurada[] {
    return this.tablasConfiguradas.filter(config => config.seccion === seccion)
  }


  selectTab(tabId: string): void {
    this.activeTab.set(tabId);
  }
}
